issue_context.body:
## Enhancement

`FieldType` is a common used structure by runtime,  attributes of which are public read/written.  Bugs due to erroneously changing those public attributes among function calls were reported.  To reduce such risk, we need to provide Getter and Setter functions for `FieldType`.

The core change is in ```parser/types/field_type.go``` as below,  and ~280 files need to be changed.
```diff
diff --git a/parser/types/field_type.go b/parser/types/field_type.go
index 887f33b94..5ecbd033f 100644
--- a/parser/types/field_type.go
+++ b/parser/types/field_type.go
@@ -38,12 +38,12 @@ var (
 
 // FieldType records field type information.
 type FieldType struct {
-       Tp      byte
-       Flag    uint
-       Flen    int
-       Decimal int
-       Charset string
-       Collate string
+       tp      byte
+       flag    uint
+       flen    int
+       decimal int
+       charset string
+       collate string
        // Elems is the element list for enum and set type.
        Elems []string
 }

+// NewFieldTypeWithoutElems returns a FieldType
+func NewFieldTypeWithoutElems(tp byte, flag uint, flen int, decimal int, charset string, collate string) *FieldType {
+	return &FieldType{
+		tp:      tp,
+		flag:    flag,
+		flen:    flen,
+		decimal: decimal,
+		charset: charset,
+		collate: collate,
+	}
+}

+// NewFieldTypeWithoutElems returns a none string FieldType
+func NewNonStrFieldType(tp byte, flag uint, flen int, decimal int) *FieldType {
+	return &FieldType{
+		tp:      tp,
+		flag:    flag,
+		flen:    flen,
+		decimal: decimal,
+	}
+}

 func NewFieldType(tp byte) *FieldType {
+       ft := &FieldType{
+               tp:      tp,
+               flen:    UnspecifiedLength,
+               decimal: UnspecifiedLength,
+       }
+       ft.charset, ft.collate = DefaultCharsetForType(tp)
+       return ft
+}
+
+// NewFieldTypeWithCollation returns a FieldType,
+// with a type and other information about field type.
+func NewFieldTypeWithCollation(tp byte, collation string, length int) *FieldType {
+       coll, _ := charset.GetCollationByName(collation)
        return &FieldType{
-               Tp:      tp,
-               Flen:    UnspecifiedLength,
-               Decimal: UnspecifiedLength,
+               tp:      tp,
+               flen:    length,
+               decimal: UnspecifiedLength,
+               collate: collation,

+               charset: coll.CharsetName,
+       }
+}
+
+func (ft *FieldType) GetType() byte {
+       return ft.tp
+}
+
+func (ft *FieldType) SetFlag(flag uint) {
+       ft.ft.flag = flag
+}
+
+func (ft *MutableFieldType) SetFlen(flen int) {
+       ft.ft.flen = flen
+}
+
+func (ft *MutableFieldType) SetDecimal(decimal int) {
+       ft.ft.decimal = decimal
+}
+
+func (ft *MutableFieldType) SetCharset(charset string) {
+       ft.ft.charset = charset
+}
+
+func (ft *MutableFieldType) SetCollate(collate string) {
+       ft.ft.collate = collate
+}
+

```
